import React, { useState } from "react";

function Login() {
  const [isLogin, setIsLogin] = useState(true);

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    role: "PATIENT",
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (isLogin) {
      // LOGIN
      const user = {
        name: "Mithilesh",
        email: form.email,
        role: "PATIENT",
        token: "dummy-token",
      };

      localStorage.setItem("user", JSON.stringify(user));
      alert("Login Successful");
    } else {
      // REGISTER
      console.log(form);
      alert(`Registered as ${form.role}`);

      setIsLogin(true); // switch to login
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Toggle Tabs */}
        <div style={styles.toggle}>
          <button
            style={isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(true)}
          >
            Sign In
          </button>
          <button
            style={!isLogin ? styles.activeTab : styles.tab}
            onClick={() => setIsLogin(false)}
          >
            Sign Up
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} style={styles.form}>
          {/* Name (only for signup) */}
          {!isLogin && (
            <input
              style={styles.input}
              placeholder="Name"
              onChange={(e) =>
                setForm({ ...form, name: e.target.value })
              }
            />
          )}

          {/* Email */}
          <input
            style={styles.input}
            placeholder="Email"
            onChange={(e) =>
              setForm({ ...form, email: e.target.value })
            }
          />

          {/* Password */}
          <input
            style={styles.input}
            type="password"
            placeholder="Password"
            onChange={(e) =>
              setForm({ ...form, password: e.target.value })
            }
          />

          {/* Role Dropdown (only signup) */}
          {!isLogin && (
            <select
              style={styles.input}
              value={form.role}
              onChange={(e) =>
                setForm({ ...form, role: e.target.value })
              }
            >
              <option value="PATIENT">Patient</option>
              <option value="DOCTOR">Doctor</option>
              <option value="ADMIN">Admin</option>
            </select>
          )}

          {/* Submit Button */}
          <button style={styles.submitBtn}>
            {isLogin ? "Login" : "Register"}
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "80vh",
    background: "#f5f5f5",
  },
  card: {
    width: "320px",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
    background: "#fff",
  },
  toggle: {
    display: "flex",
    marginBottom: "15px",
  },
  tab: {
    flex: 1,
    padding: "10px",
    border: "none",
    background: "#eee",
    cursor: "pointer",
  },
  activeTab: {
    flex: 1,
    padding: "10px",
    border: "none",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },
  input: {
    padding: "8px",
    borderRadius: "5px",
    border: "1px solid #ccc",
  },
  submitBtn: {
    marginTop: "10px",
    padding: "10px",
    background: "#1976d2",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default Login;
